@CovariantOriginal.jE_mem : ∀ {l : ℕ} [inst : Fact (Nat.Prime l)] {E Ω : Type} [inst_1 : Field E]
  [inst_2 : NumberField E] [inst_3 : Field Ω] [inst_4 : Algebra E Ω] (j : Ω →+* PadicAlgCl l) (x : E),
  (CovariantOriginal.jE j) x ∈ CovariantOriginal.KwF j

@CovariantOriginal.column_matrix_mul_inverse : ∀ {l : ℕ} [hl : Fact (Nat.Prime l)] {E Ω : Type} [inst : Field E]
  [inst_1 : NumberField E] [inst_2 : Field Ω] [inst_3 : Algebra E Ω] {j : Ω →+* PadicAlgCl l}
  (σ : ↥(CovariantOriginal.KwF j).fixingSubgroup), ↑σ ∈ (CovariantOriginal.KwF j).fixingSubgroup

@CovariantOriginal.padic_embedding_algebra_compat : ∀ {l : ℕ} [hl : Fact (Nat.Prime l)] {E Ω : Type} [inst : Field E]
  [inst_1 : NumberField E] [inst_2 : Field Ω] [inst_3 : Algebra E Ω] {j : Ω →+* PadicAlgCl l},
  ↑1 ∈ (CovariantOriginal.KwF j).fixingSubgroup

@CovariantOriginal.conj_invariant_character_mem : ∀ {l : ℕ} [hl : Fact (Nat.Prime l)] {E Ω : Type} [inst : Field E]
  [inst_1 : NumberField E] [inst_2 : Field Ω] [inst_3 : Algebra E Ω] {j : Ω →+* PadicAlgCl l}
  (σ τ : ↥(CovariantOriginal.KwF j).fixingSubgroup), ↑(σ * τ) ∈ (CovariantOriginal.KwF j).fixingSubgroup

@CovariantOriginal.conj_invariant_character_transport : ∀ {l : ℕ} [hl : Fact (Nat.Prime l)] {E Ω : Type}
  [inst : Field E] [inst_1 : NumberField E] [inst_2 : Field Ω] [inst_3 : Algebra E Ω] [inst_4 : IsAlgClosure E Ω]
  [inst_5 : CharZero Ω] [inst_6 : IsAlgClosure ℚ Ω] {j : Ω →+* PadicAlgCl l} {A : ValuationSubring Ω}
  (hj : ∀ (x : Ω), x ∈ A ↔ ‖j x‖ ≤ 1) (σ τ : ↥(CovariantOriginal.KwF j).fixingSubgroup),
  ⟨CovariantOriginal.resE j ↑(σ * τ) ⋯, ⋯⟩ = ⟨CovariantOriginal.resE j ↑σ ⋯, ⋯⟩ * ⟨CovariantOriginal.resE j ↑τ ⋯, ⋯⟩

@CovariantOriginal.j_resQ : ∀ {l : ℕ} [inst : Fact (Nat.Prime l)] {Ω : Type} [inst_1 : Field Ω] [inst_2 : CharZero Ω]
  [inst_3 : IsAlgClosure ℚ Ω] (j : Ω →+* PadicAlgCl l) (σ : CovariantOriginal.GQ l) (x : Ω),
  j ((CovariantOriginal.resQ j σ) x) = σ (j x)
